SET search_path TO fraudops;
TRUNCATE TABLE data_quality_result, rule_execution, model_prediction, fraud_decision, fraud_alert, case_alert, case_action, fraud_feedback, fraud_case, "transaction", data_quality_rule, model_version, threshold_configuration, fraud_rule, merchant, device, card, account, customer RESTART IDENTITY CASCADE;
COPY customer (customer_id,customer_external_id,full_name,email,phone_number,home_country,home_city,customer_segment,risk_tier,opened_at) FROM '/tmp/fraudops-sample/customer.csv' WITH (FORMAT csv, HEADER true);
COPY account (account_id,customer_id,account_external_id,account_type,currency,opened_at,status) FROM '/tmp/fraudops-sample/account.csv' WITH (FORMAT csv, HEADER true);
COPY card (card_id,account_id,card_external_id,card_network,last_four,issued_at,expires_at,status) FROM '/tmp/fraudops-sample/card.csv' WITH (FORMAT csv, HEADER true);
COPY device (device_id,customer_id,device_external_id,device_type,operating_system,first_seen_at,trusted) FROM '/tmp/fraudops-sample/device.csv' WITH (FORMAT csv, HEADER true);
COPY merchant (merchant_id,merchant_external_id,merchant_name,merchant_category_code,merchant_category,country,city,risk_tier) FROM '/tmp/fraudops-sample/merchant.csv' WITH (FORMAT csv, HEADER true);
COPY "transaction" (transaction_id,transaction_external_id,customer_id,account_id,card_id,device_id,merchant_id,transaction_at,amount,currency,merchant_country,merchant_city,channel,status,authorization_code,fraud_label,label_source,label_available_at,chargeback_date,analyst_confirmed_at,fraud_scenario) FROM '/tmp/fraudops-sample/transaction.csv' WITH (FORMAT csv, HEADER true);
COPY fraud_rule (fraud_rule_id,rule_code,rule_name,description,severity,active) FROM '/tmp/fraudops-sample/fraud_rule.csv' WITH (FORMAT csv, HEADER true);
COPY threshold_configuration (threshold_configuration_id,configuration_name,step_up_threshold,manual_review_threshold,hold_decline_threshold,effective_from,effective_to) FROM '/tmp/fraudops-sample/threshold_configuration.csv' WITH (FORMAT csv, HEADER true);
COPY model_version (model_version_id,model_name,version_label,training_started_at,training_completed_at,metrics,artifact_uri,promoted) FROM '/tmp/fraudops-sample/model_version.csv' WITH (FORMAT csv, HEADER true);
COPY data_quality_rule (data_quality_rule_id,rule_code,table_name,column_name,description,severity,active) FROM '/tmp/fraudops-sample/data_quality_rule.csv' WITH (FORMAT csv, HEADER true);
SELECT 'customer' AS table_name, count(*) FROM customer UNION ALL SELECT 'account', count(*) FROM account UNION ALL SELECT 'card', count(*) FROM card UNION ALL SELECT 'device', count(*) FROM device UNION ALL SELECT 'merchant', count(*) FROM merchant UNION ALL SELECT 'transaction', count(*) FROM "transaction" UNION ALL SELECT 'fraud_rule', count(*) FROM fraud_rule UNION ALL SELECT 'threshold_configuration', count(*) FROM threshold_configuration UNION ALL SELECT 'model_version', count(*) FROM model_version UNION ALL SELECT 'data_quality_rule', count(*) FROM data_quality_rule ORDER BY table_name;
